def generate_zsh_completions(cmdname, options):
    zsh_completions = f"#compdef {cmdname}\n\n"
    zsh_completions += "_arguments \\\n"
    for option in options:
        # Format each option for Zsh completion
        zsh_completions += f"  '{option}' \\\n"
    zsh_completions = zsh_completions.rstrip(" \\\n") + "\n"
    return zsh_completions

